package chat.oldy;
import android.view.*;import org.json.JSONObject;

/** Long press is available on the whole message, including media and nested controls. */
final class MessageSelection {
 static void bind(MainActivity a,View view,JSONObject message){view.setOnLongClickListener(v->{v.performHapticFeedback(HapticFeedbackConstants.LONG_PRESS);v.startActionMode(new ActionMode.Callback(){public boolean onCreateActionMode(ActionMode mode,Menu menu){mode.setTitle(I18n.t("Выбрано 1"));menu.add(0,1,0,I18n.t("Ответить")).setShowAsAction(MenuItem.SHOW_AS_ACTION_IF_ROOM);menu.add(0,2,1,I18n.t("Копировать")).setShowAsAction(MenuItem.SHOW_AS_ACTION_IF_ROOM);menu.add(0,3,2,I18n.t("Действия")).setShowAsAction(MenuItem.SHOW_AS_ACTION_IF_ROOM);try{boolean allowed=message.optBoolean("out")||a.vault.moderator()||!Conversation.community(a.chat);if(allowed)menu.add(0,4,3,I18n.t("Удалить")).setShowAsAction(MenuItem.SHOW_AS_ACTION_IF_ROOM);}catch(Exception ignored){}view.setAlpha(.72f);return true;}public boolean onPrepareActionMode(ActionMode m,Menu menu){return false;}public void onDestroyActionMode(ActionMode m){view.setAlpha(1);}public boolean onActionItemClicked(ActionMode mode,MenuItem item){mode.finish();if(item.getItemId()==1&&a.compose!=null){a.replyTo=message;a.renderReply();a.compose.requestFocus();}else if(item.getItemId()==2){a.getSystemService(android.content.ClipboardManager.class).setPrimaryClip(android.content.ClipData.newPlainText("Oldi",message.optString("text")));}else if(item.getItemId()==4)a.deletePost(message);else a.messageMenu(message);return true;}},ActionMode.TYPE_FLOATING);return true;});if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)bind(a,group.getChildAt(i),message);}}
}
